(function () {
  "use strict";
  // Layer JS loads on every page: it does nothing without a workbench.
  var workbench = document.querySelector("[data-studio-workbench]");
  if (!workbench) {
    return;
  }

  // The workbench of branch T (data-studio-branch). The page itself renders
  // on S, which scrud-ui.js sends (Scrud-UI-Branch); this script never does.
  var BRANCH = workbench.getAttribute("data-studio-branch") || "";
  var PUBLISHED = workbench.getAttribute("data-studio-published") === "true";
  var PANES = ["items", "editor", "preview"];
  var PANES_KEY = "studio:panes";
  // The workbench state in the URL's query; every other parameter
  // (ui-scope=studio, ui-mode=view, ui-safe) is kept as it is.
  var STATE_KEYS = [
    "type",
    "item",
    "pointer",
    "mode",
    "context",
    "scope",
    "instance",
    "pinned"
  ];
  var MAX_ERROR = 500;
  var EDITOR_SCOPE = "studio studio-editor";
  var DRAFT_DELAY = 300;
  var MAX_DRAFT_ERRORS = 50;
  var REVERT_LABEL = "Revert to inherited";
  var DRAFTS_UNREPORTED =
    "The preview could not report its errors: a draft may not be shown.";
  var REVERT_CONFIRM =
    "Revert to inherited? This branch's own version of the item is deleted.";
  var DELETE_LABEL = "Delete";
  var DELETE_CONFIRM =
    "Delete this item from this branch? The branch has no inherited" +
    " version of it you can read to show instead.";

  function find(selector) {
    return workbench.querySelector(selector);
  }

  // ---- panes: collapsed to a rail, remembered per viewer ------------------

  // {items: true} for a collapsed pane. Storage may be missing or refuse
  // (private mode, a policy): the page works without it.
  function loadPanes() {
    var collapsed = {};
    try {
      var stored = JSON.parse(window.localStorage.getItem(PANES_KEY) || "{}");
      PANES.forEach(function (name) {
        if (name !== "preview" && stored && stored[name] === true) {
          collapsed[name] = true;
        }
      });
    } catch (e) {
      return {};
    }
    return collapsed;
  }

  function savePanes(collapsed) {
    try {
      window.localStorage.setItem(PANES_KEY, JSON.stringify(collapsed));
    } catch (e) {
      // Not remembered; the panes still change.
    }
  }

  function showPanes(collapsed) {
    PANES.forEach(function (name) {
      var closed = collapsed[name] === true;
      var pane = find('[data-studio-pane="' + name + '"]');
      var toggle = find('[data-studio-toggle="' + name + '"]');
      if (pane && closed) pane.setAttribute("data-studio-collapsed", "");
      if (pane && !closed) pane.removeAttribute("data-studio-collapsed");
      if (toggle) toggle.setAttribute("aria-pressed", closed ? "false" : "true");
    });
  }

  var panes = loadPanes();

  function togglePane(name) {
    // The preview can't be hidden.
    if (name !== "items" && name !== "editor") return;
    if (panes[name]) delete panes[name];
    else panes[name] = true;
    showPanes(panes);
    savePanes(panes);
  }

  // ---- state in the URL ---------------------------------------------------

  function query() {
    return new URLSearchParams(window.location.search);
  }

  function readState() {
    var params = query();
    var state = {};
    STATE_KEYS.forEach(function (key) {
      var value = params.get(key);
      if (value !== null && value !== "") state[key] = value;
    });
    return state;
  }

  // Merge `changes` (null or "" removes a key; unknown keys are ignored)
  // into the URL. A new type re-fetches the strip and the preview.
  function setState(changes) {
    var before = readState();
    var params = query();
    Object.keys(changes || {}).forEach(function (key) {
      if (STATE_KEYS.indexOf(key) < 0) return;
      var value = changes[key];
      if (value === null || value === undefined || value === "") {
        params.delete(key);
      } else {
        params.set(key, String(value));
      }
    });
    var search = params.toString();
    var location = window.location;
    window.history.replaceState(
      window.history.state,
      "",
      location.pathname + (search ? "?" + search : "") + (location.hash || "")
    );
    var after = readState();
    if (before.type !== after.type) {
      refresh("status");
      submitPreview({});
    }
    return after;
  }

  // The key of an item in `item`: "<kind>:<name>", and "@<applies_to>" for a
  // stylesheet that applies to a context (names have no "@").
  function itemKey(open) {
    var key = open.kind + ":" + open.name;
    return open.applies_to ? key + "@" + open.applies_to : key;
  }

  // ---- panes embedded from T's studio data --------------------------------

  // The pane's URL; the strip's with ?type=<type> when the state has one,
  // since a component can't read the page's query (browse_url needs it).
  function paneUrl(container) {
    var url = container.getAttribute("data-studio-src") || "";
    var type = readState().type;
    if (type && container.getAttribute("data-studio-embed") === "status") {
      url += (url.indexOf("?") < 0 ? "?" : "&") + "type=" + encodeURIComponent(type);
    }
    return url;
  }

  // Fetch the pane again in its own scope (scrud-ui.js adds the branch and
  // safe mode).
  function refresh(name) {
    var container = find('[data-studio-embed="' + name + '"]');
    var htmx = window.htmx;
    if (!container || !htmx || typeof htmx.ajax !== "function") return;
    htmx.ajax("GET", paneUrl(container), {
      source: container,
      target: container,
      swap: "innerHTML",
      headers: { "Scrud-UI-Scope": container.getAttribute("data-studio-scope") }
    });
  }

  // ---- the bare live preview ----------------------------------------------

  // The drafts the preview shows (JSON), or null: typing that changes
  // nothing sends nothing.
  var lastDrafts = null;

  // The studio's endpoints, from the strip; null when its URLs are not
  // included (or the strip is not there).
  function endpoints() {
    var holder = find("[data-studio-endpoints]");
    if (!holder) return null;
    try {
      var value = JSON.parse(holder.getAttribute("data-studio-endpoints"));
      return value && typeof value === "object" ? value : null;
    } catch (e) {
      return null;
    }
  }

  function csrfToken() {
    var meta = document.querySelector('meta[name="csrf-token"]');
    return meta ? meta.getAttribute("content") || "" : "";
  }

  function previewRequest(state, extra) {
    var pinned = state.pinned === "1" || state.pinned === "true";
    var instance = state.instance === undefined ? null : state.instance;
    if (instance !== null && /^[0-9]+$/.test(instance)) instance = Number(instance);
    return {
      type: state.type,
      branch: pinned ? BRANCH + "@pinned" : BRANCH,
      mode: state.mode || "view",
      scope: String(state.scope || "")
        .split(/[\s,]+/)
        .filter(Boolean),
      context: state.context || "",
      instance: instance,
      // A published T is read-only: its preview sends no drafts.
      drafts: !PUBLISHED && Array.isArray(extra.drafts) ? extra.drafts : [],
      mark: extra.mark || null,
      after_push: extra.after_push || null
    };
  }

  // Submit the preview form into the sandboxed frame: the URL state merged
  // with `extra` ({drafts, mark, after_push}). Nothing without a type or
  // the endpoints; returns whether it was sent.
  function submitPreview(extra) {
    var state = readState();
    var where = endpoints();
    var form = find("[data-studio-preview-form]");
    if (!state.type || !where || typeof where.live_preview !== "string" || !form) {
      return false;
    }
    var token = form.querySelector('[name="csrfmiddlewaretoken"]');
    var request = form.querySelector('[name="request"]');
    if (!token || !request) return false;
    var sent = previewRequest(state, extra || {});
    form.setAttribute("action", where.live_preview);
    token.value = csrfToken();
    request.value = JSON.stringify(sent);
    lastDrafts = sent.drafts.length ? JSON.stringify(sent.drafts) : null;
    form.submit();
    return true;
  }

  // ---- writes -------------------------------------------------------------

  function clean(text) {
    return String(text || "")
      .replace(/\s+/g, " ")
      .trim();
  }

  // The server's error text for a refused request: a problem's title and
  // detail, else the notices of the HTML it answered (else its text).
  function errorText(xhr) {
    var status = xhr && xhr.status;
    if (!status) return "The request failed (network error).";
    var body = String(xhr.responseText || "");
    var type = xhr.getResponseHeader ? String(xhr.getResponseHeader("Content-Type") || "") : "";
    var text = "";
    if (/json/.test(type)) {
      try {
        var problem = JSON.parse(body);
        text = [problem.title, problem.detail]
          .filter(function (part) {
            return typeof part === "string" && part;
          })
          .join(": ");
      } catch (e) {
        text = "";
      }
    } else if (body && typeof DOMParser === "function") {
      // An inert document: nothing in it runs or loads.
      var doc = new DOMParser().parseFromString(body, "text/html");
      var notices = Array.prototype.slice.call(doc.querySelectorAll(".scrud-notice"));
      var parts = notices.length ? notices : doc.body ? [doc.body] : [];
      text = parts
        .map(function (part) {
          return clean(part.textContent);
        })
        .filter(Boolean)
        .join(" ");
    }
    text = clean(text).slice(0, MAX_ERROR);
    return "Refused (HTTP " + status + ")" + (text ? ": " + text : ".");
  }

  function showError(text) {
    var notice = find("[data-studio-notice]");
    if (!notice) return;
    notice.textContent = text;
    notice.removeAttribute("hidden");
  }

  function clearError() {
    var notice = find("[data-studio-notice]");
    if (!notice) return;
    notice.textContent = "";
    notice.setAttribute("hidden", "");
  }

  // Any write from the workbench (an action, an editor's frame): on success
  // the items, the strip and the preview show the new state; a refusal
  // shows the server's text. htmx fires it again on an ancestor still in
  // the page when the element was swapped out, so the event's target counts.
  document.addEventListener("htmx:afterRequest", function (evt) {
    if (!evt.target || !workbench.contains(evt.target)) return;
    var detail = evt.detail || {};
    var verb = String((detail.requestConfig || {}).verb || "").toLowerCase();
    if (!verb || verb === "get") return;
    if (detail.successful) {
      clearError();
      // An override or a revert (or a push) changes what the open item is:
      // it opens again from the refreshed tree. A save's response is the
      // editor itself.
      if (verb === "post" || verb === "delete") reopenPending = true;
      refresh("items");
      refresh("status");
      submitPreview({});
    } else {
      showError(errorText(detail.xhr));
    }
  });

  // ---- the editor ---------------------------------------------------------

  var editorBody = find("[data-studio-editor]");
  var editorHead = find("[data-studio-editor-head]");
  var draftErrors = find("[data-studio-draft-errors]");
  // Open the item again when the items pane has been fetched again.
  var reopenPending = false;
  var draftTimer = null;
  // The open item's data-studio-open (its `reverts_to` labels the delete).
  var current = null;

  function parseOpen(entry) {
    var open;
    try {
      open = JSON.parse(entry.getAttribute("data-studio-open"));
    } catch (e) {
      return null;
    }
    if (!open || typeof open.kind !== "string" || typeof open.name !== "string") {
      return null;
    }
    return open;
  }

  function hasClass(element, name) {
    var classes = " " + (element.getAttribute("class") || "") + " ";
    return classes.indexOf(" " + name + " ") >= 0;
  }

  function empty(node) {
    while (node.firstChild) node.removeChild(node.firstChild);
  }

  // A new element with `text` as its text (never markup).
  function append(parent, tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.setAttribute("class", className);
    if (text !== undefined) node.textContent = text;
    parent.appendChild(node);
    return node;
  }

  // The tree's entry for an item key (state `item`), or null.
  function entryFor(key) {
    var container = find('[data-studio-embed="items"]');
    var all = container ? container.querySelectorAll("[data-studio-open]") : [];
    for (var i = 0; i < all.length; i++) {
      var open = parseOpen(all[i]);
      if (open && itemKey(open) === key) return all[i];
    }
    return null;
  }

  function cancelDraft() {
    if (draftTimer !== null) window.clearTimeout(draftTimer);
    draftTimer = null;
  }

  // The editor pane's header: the item, where it comes from, and for an
  // item T does not own the tree's own "Override on this branch" button (a
  // copy: its body is the server's).
  function showHead(open, item) {
    if (!editorHead) return;
    empty(editorHead);
    var title = open.kind + " " + open.name;
    if (open.applies_to) title += " (" + open.applies_to + ")";
    append(editorHead, "h3", "studio-editor-title", title);
    var origin = item ? item.querySelector(".studio-origin") : null;
    if (origin) {
      append(editorHead, "span", "studio-editor-origin", clean(origin.textContent));
    }
    var override = item && !PUBLISHED ? item.querySelector(".studio-override") : null;
    if (override) {
      var copy = override.cloneNode(true);
      editorHead.appendChild(copy);
      var htmx = window.htmx;
      if (htmx && typeof htmx.process === "function") htmx.process(copy);
    }
    editorHead.removeAttribute("hidden");
  }

  function showHint(text) {
    if (editorHead) {
      empty(editorHead);
      editorHead.setAttribute("hidden", "");
    }
    if (!editorBody) return;
    empty(editorBody);
    append(editorBody, "p", "studio-hint", text);
  }

  // Load the item into the editor: its resource in the editor's scope, in
  // view mode when T is published or the item is not T's own (the resource
  // view then gives edit mode only to a user who may PUT it). An item with
  // no URL shows its content, as text.
  function loadEditor(open, entry) {
    if (!editorBody) return;
    current = open;
    cancelDraft();
    showDraftErrors(null);
    var item = entry && entry.closest ? entry.closest(".studio-item") : null;
    var own = !!item && hasClass(item, "studio-own");
    showHead(open, item);
    if (typeof open.href === "string" && open.href) {
      var htmx = window.htmx;
      if (!htmx || typeof htmx.ajax !== "function") return;
      var headers = { "Scrud-UI-Scope": EDITOR_SCOPE };
      if (PUBLISHED || !own) headers["Scrud-UI-Mode"] = "view";
      htmx.ajax("GET", open.href, {
        source: editorBody,
        target: editorBody,
        swap: "innerHTML",
        headers: headers
      });
      return;
    }
    empty(editorBody);
    var holder = item ? item.querySelector("[data-studio-content]") : null;
    var text;
    try {
      // tojson's text: \u escapes for <, >, & and '.
      text = JSON.stringify(JSON.parse(holder.textContent), null, 2);
    } catch (e) {
      text = "The item's content could not be read.";
    }
    append(editorBody, "pre", "studio-code studio-content", text);
  }

  // Open the item the state names, from the tree as it is now.
  function reopen() {
    var key = readState().item;
    if (!key) return;
    var entry = entryFor(key);
    var open = entry ? parseOpen(entry) : null;
    if (!open) {
      showHint(key + " is not on this branch.");
      return;
    }
    workbench.dispatchEvent(
      new CustomEvent("studio:open", { detail: { open: open, entry: entry } })
    );
  }

  // The frame's Delete button deletes T's own row, the one control that
  // does: "Revert to inherited" when the branch then shows an ancestor's or
  // a packaged item (`reverts_to`), else a delete that says so.
  function decorateEditor() {
    var frame = editorBody ? editorBody.querySelector(".scrud-resource") : null;
    if (!frame) return;
    var href = frame.getAttribute("data-scrud-href");
    var buttons = frame.querySelectorAll("button[hx-delete]");
    for (var i = 0; i < buttons.length; i++) {
      var button = buttons[i];
      if (button.getAttribute("hx-delete") !== href) continue;
      if (button.closest(".scrud-resource") !== frame) continue;
      var reverts = !!(current && current.reverts_to);
      button.textContent = reverts ? REVERT_LABEL : DELETE_LABEL;
      button.setAttribute("hx-confirm", reverts ? REVERT_CONFIRM : DELETE_CONFIRM);
      button.setAttribute("class", reverts ? "studio-revert" : "studio-delete");
    }
  }

  // The frame's own content (its scrud-content, not a nested frame's).
  function contentOf(frame) {
    var scripts = frame.querySelectorAll("script.scrud-content");
    for (var i = 0; i < scripts.length; i++) {
      if (scripts[i].closest(".scrud-resource") !== frame) continue;
      try {
        return JSON.parse(scripts[i].textContent);
      } catch (e) {
        return null;
      }
    }
    return null;
  }

  // The draft of the editor's item: the frame's content with the code
  // applied at its pointer (/template, /css or /js). None in view mode.
  function draftOf(code) {
    var frame = code.closest(".scrud-resource");
    var editor = code.closest("[data-studio-editor-item]");
    if (!frame || !editor || !frame.hasAttribute("hx-put")) return null;
    var field = /^\/([a-z]+)$/.exec(code.getAttribute("name") || "");
    var kind = editor.getAttribute("data-studio-kind");
    var content = contentOf(frame);
    if (!field || !kind || !content || typeof content !== "object") return null;
    if (Array.isArray(content)) return null;
    content[field[1]] = code.value;
    return { kind: kind, content: content };
  }

  function sendDraft(code) {
    draftTimer = null;
    // Replaced meanwhile (saved, reloaded, another item opened).
    if (!editorBody || !editorBody.contains(code)) return;
    var draft = draftOf(code);
    if (!draft || JSON.stringify([draft]) === lastDrafts) return;
    submitPreview({ drafts: [draft] });
  }

  // The drafts the preview left out, as text; `report` is the bridge's
  // message, or null to hide them.
  function showDraftErrors(report) {
    if (!draftErrors) return;
    empty(draftErrors);
    if (report && report.failed === true) {
      append(draftErrors, "p", "studio-draft-failed", DRAFTS_UNREPORTED);
      draftErrors.removeAttribute("hidden");
      return;
    }
    var errors = report && Array.isArray(report.errors) ? report.errors : [];
    if (!errors.length) {
      draftErrors.setAttribute("hidden", "");
      return;
    }
    append(draftErrors, "p", "studio-draft-errors-title", "Not shown in the preview:");
    var list = append(draftErrors, "ul", "studio-draft-error-list", "");
    errors.slice(0, MAX_DRAFT_ERRORS).forEach(function (error) {
      var e = error && typeof error === "object" ? error : {};
      var messages = Array.isArray(e.messages) ? e.messages.map(String).join(" ") : "";
      var what = clean(String(e.kind || "") + " " + String(e.name || ""));
      append(list, "li", "", (what + ": " + clean(messages)).slice(0, MAX_ERROR));
    });
    draftErrors.removeAttribute("hidden");
  }

  workbench.addEventListener("studio:open", function (evt) {
    var detail = evt.detail || {};
    if (!detail.open) return;
    loadEditor(detail.open, detail.entry || entryFor(itemKey(detail.open)));
  });

  // A change of the code is no save (the frame saves on change): Save is.
  // A draft is never stored.
  workbench.addEventListener(
    "change",
    function (evt) {
      var target = evt.target;
      if (!target || typeof target.closest !== "function") return;
      if (!target.closest("[data-studio-code]")) return;
      if (editorBody && editorBody.contains(target)) evt.stopPropagation();
    },
    true
  );

  // Live typing: the editor's content as a draft in the preview, once the
  // typing pauses. None on a published T, or without a type to preview.
  workbench.addEventListener("keyup", function (evt) {
    var target = evt.target;
    if (!target || typeof target.closest !== "function") return;
    var code = target.closest("[data-studio-code]");
    if (!code || !editorBody || !editorBody.contains(code)) return;
    if (PUBLISHED || !readState().type) return;
    cancelDraft();
    draftTimer = window.setTimeout(function () {
      sendDraft(code);
    }, DRAFT_DELAY);
  });

  document.addEventListener("htmx:afterSwap", function (evt) {
    var target = evt.target;
    if (!target) return;
    var items = find('[data-studio-embed="items"]');
    if (items && target === items && reopenPending) {
      reopenPending = false;
      reopen();
    } else if (editorBody && (target === editorBody || editorBody.contains(target))) {
      decorateEditor();
    }
  });

  // The bridge's report of the drafts it left out. Only from the preview's
  // own window, and only this shape: the branch's scripts can post too.
  window.addEventListener("message", function (evt) {
    var frame = find("iframe.studio-preview");
    if (!frame || !frame.contentWindow || evt.source !== frame.contentWindow) return;
    var data = evt.data;
    if (!data || typeof data !== "object") return;
    if (data.type === "scrud-preview:errors") showDraftErrors(data);
  });

  // ---- clicks -------------------------------------------------------------

  function openItem(entry) {
    var open = parseOpen(entry);
    if (!open) return;
    setState({ item: itemKey(open) });
    // The editor loads it.
    workbench.dispatchEvent(
      new CustomEvent("studio:open", { detail: { open: open, entry: entry } })
    );
  }

  workbench.addEventListener("click", function (evt) {
    var target = evt.target;
    if (!target || typeof target.closest !== "function") return;
    var toggle = target.closest("[data-studio-toggle]");
    if (toggle) {
      togglePane(toggle.getAttribute("data-studio-toggle"));
      return;
    }
    var entry = target.closest("[data-studio-open]");
    if (entry) openItem(entry);
  });

  // ---- start --------------------------------------------------------------

  showPanes(panes);
  window.ScrudStudio = {
    branch: BRANCH,
    published: PUBLISHED,
    state: readState,
    setState: setState,
    itemKey: itemKey,
    refresh: refresh,
    submitPreview: submitPreview,
    errorText: errorText,
    reopen: reopen
  };
  if (readState().type) {
    refresh("status");
    submitPreview({});
  }
  reopen();
  workbench.setAttribute("data-studio-ready", "1");
})();
